import csv
def load(path):
    with open(path, encoding='utf-8') as f:
        return list(csv.DictReader(f))

rows06 = load('../06/outputs/01_SOURCE_LEDGER.csv')
rows10a = load('evidence/10A_HYBRID_SOURCES.csv')
rows10b = load('evidence/10B_RADIATION_SOURCES.csv')

print('=== 06 total', len(rows06), '10A total', len(rows10a), '10B total', len(rows10b))

def norm_doi(d):
    d = (d or '').strip().lower()
    for p in ['https://doi.org/','http://doi.org/','doi:']:
        if d.startswith(p): d = d[len(p):]
    return d

all_dois = set()
for r in rows06+rows10a+rows10b:
    d = norm_doi(r.get('doi'))
    if d: all_dois.add(d)
print('total unique normalized DOIs across all 3 ledgers so far:', len(all_dois))
with open('/tmp/all_dois.txt','w',encoding='utf-8') as f:
    for d in sorted(all_dois):
        f.write(d+'\n')
